# Phoenix common environment variables

## CAUTION: Do NOT source this directly!
## Source 'env.sh' instead.

## Additionally, if you need to override any variables here, export them to your shell manually or use `env_override.sh`.
## Do NOT edit this file directly.

# If variables are defined with a custom `env_override.sh` file (located at the root project directory), let's use those
## These need to be set first, to ensure that they don't interfere with certain variables
readonly PHOENIX_ENV_OVERRIDE="${PHOENIX_ROOT}/env_override.sh"
if [[ -f "${PHOENIX_ENV_OVERRIDE}" ]]; then
    source "${PHOENIX_ENV_OVERRIDE}"
fi

# Phoenix

# Scripts directory
readonly PHOENIX_SCRIPTS="${PHOENIX_ROOT}/scripts"
export PHOENIX_SCRIPTS

# Set our platform, OS, and architecture
readonly PHOENIX_ENV_HELPERS="${PHOENIX_SCRIPTS}/env_helpers.sh"
export PHOENIX_ENV_HELPERS
source "${PHOENIX_ENV_HELPERS}"

# Whether we're being invoked from a Nix flake
readonly PHOENIX_NIX_DEFAULT=0
if [[ -z "${PHOENIX_NIX+x}" ]]; then
    readonly PHOENIX_NIX="${PHOENIX_NIX_DEFAULT}"
else
    readonly PHOENIX_NIX="${PHOENIX_NIX}"
fi
export PHOENIX_NIX

# Version info
readonly PHOENIX_VERSIONS="${PHOENIX_SCRIPTS}/versions.sh"
export PHOENIX_VERSIONS

# Archives directory
readonly PHOENIX_ARCHIVES="${PHOENIX_ROOT}/archives"
export PHOENIX_ARCHIVES

# Build directory
readonly PHOENIX_BUILD_DEFAULT="${PHOENIX_ROOT}/build"
if [[ -z "${PHOENIX_BUILD+x}" ]]; then
    if [ "${PHOENIX_NIX}" == 1 ]; then
        # Nix needs to use /tmp here, see https://codeberg.org/celenity/Dove/issues/59
        readonly PHOENIX_BUILD='/tmp/phoenix/build'
    else
        readonly PHOENIX_BUILD="${PHOENIX_BUILD_DEFAULT}"
    fi
else
    readonly PHOENIX_BUILD="${PHOENIX_BUILD}"
fi
export PHOENIX_BUILD

# Temporary build directory
readonly PHOENIX_TEMP="${PHOENIX_BUILD}/tmp"
export PHOENIX_TEMP

# Build resources directory
readonly PHOENIX_BUILD_RESOURCES="${PHOENIX_ROOT}/build-resources"
export PHOENIX_BUILD_RESOURCES

# Phoenix outputs directory
readonly PHOENIX_OUTPUTS_DEFAULT="${PHOENIX_ROOT}"
if [[ -z "${PHOENIX_OUTPUTS+x}" ]]; then
    readonly PHOENIX_OUTPUTS="${PHOENIX_OUTPUTS_DEFAULT}"
else
    readonly PHOENIX_OUTPUTS="${PHOENIX_OUTPUTS}"
fi
export PHOENIX_OUTPUTS

# Android outputs directory
readonly PHOENIX_ANDROID_OUTPUTS_DEFAULT="${PHOENIX_OUTPUTS}/android"
if [[ -z "${PHOENIX_ANDROID_OUTPUTS+x}" ]]; then
    readonly PHOENIX_ANDROID_OUTPUTS="${PHOENIX_ANDROID_OUTPUTS_DEFAULT}"
else
    readonly PHOENIX_ANDROID_OUTPUTS="${PHOENIX_ANDROID_OUTPUTS}"
fi
export PHOENIX_ANDROID_OUTPUTS

# Linux outputs directory
readonly PHOENIX_LINUX_OUTPUTS_DEFAULT="${PHOENIX_OUTPUTS}/linux"
if [[ -z "${PHOENIX_LINUX_OUTPUTS+x}" ]]; then
    readonly PHOENIX_LINUX_OUTPUTS="${PHOENIX_LINUX_OUTPUTS_DEFAULT}"
else
    readonly PHOENIX_LINUX_OUTPUTS="${PHOENIX_LINUX_OUTPUTS}"
fi
export PHOENIX_LINUX_OUTPUTS

## Linux (Flatpak) outputs directory
readonly PHOENIX_LINUX_FLATPAK_OUTPUTS_DEFAULT="${PHOENIX_OUTPUTS}/linux-flatpak"
if [[ -z "${PHOENIX_LINUX_FLATPAK_OUTPUTS+x}" ]]; then
    readonly PHOENIX_LINUX_FLATPAK_OUTPUTS="${PHOENIX_LINUX_FLATPAK_OUTPUTS_DEFAULT}"
else
    readonly PHOENIX_LINUX_FLATPAK_OUTPUTS="${PHOENIX_LINUX_FLATPAK_OUTPUTS}"
fi
export PHOENIX_LINUX_FLATPAK_OUTPUTS

# OS X outputs directory
readonly PHOENIX_OSX_OUTPUTS_DEFAULT="${PHOENIX_OUTPUTS}/osx"
if [[ -z "${PHOENIX_OSX_OUTPUTS+x}" ]]; then
    readonly PHOENIX_OSX_OUTPUTS="${PHOENIX_OSX_OUTPUTS_DEFAULT}"
else
    readonly PHOENIX_OSX_OUTPUTS="${PHOENIX_OSX_OUTPUTS}"
fi
export PHOENIX_OSX_OUTPUTS

## OS X (Intel) outputs directory
readonly PHOENIX_OSX_INTEL_OUTPUTS_DEFAULT="${PHOENIX_OUTPUTS}/osx-intel"
if [[ -z "${PHOENIX_OSX_INTEL_OUTPUTS+x}" ]]; then
    readonly PHOENIX_OSX_INTEL_OUTPUTS="${PHOENIX_OSX_INTEL_OUTPUTS_DEFAULT}"
else
    readonly PHOENIX_OSX_INTEL_OUTPUTS="${PHOENIX_OSX_INTEL_OUTPUTS}"
fi
export PHOENIX_OSX_INTEL_OUTPUTS

# Windows outputs directory
readonly PHOENIX_WINDOWS_OUTPUTS_DEFAULT="${PHOENIX_OUTPUTS}/windows"
if [[ -z "${PHOENIX_WINDOWS_OUTPUTS+x}" ]]; then
    readonly PHOENIX_WINDOWS_OUTPUTS="${PHOENIX_WINDOWS_OUTPUTS_DEFAULT}"
else
    readonly PHOENIX_WINDOWS_OUTPUTS="${PHOENIX_WINDOWS_OUTPUTS}"
fi
export PHOENIX_WINDOWS_OUTPUTS

# Should we create a log file for build.sh? (Default)
readonly PHOENIX_LOG_BUILD_DEFAULT=1
if [[ -z "${PHOENIX_LOG_BUILD+x}" ]]; then
    readonly PHOENIX_LOG_BUILD="${PHOENIX_LOG_BUILD_DEFAULT}"
else
    readonly PHOENIX_LOG_BUILD="${PHOENIX_LOG_BUILD}"
fi
export PHOENIX_LOG_BUILD

# Directory where we should store log files (if logging is desired)
readonly PHOENIX_LOG_DIR_DEFAULT="${PHOENIX_BUILD}/logs"
if [[ -z "${PHOENIX_LOG_DIR+x}" ]]; then
    readonly PHOENIX_LOG_DIR="${PHOENIX_LOG_DIR_DEFAULT}"
else
    readonly PHOENIX_LOG_DIR="${PHOENIX_LOG_DIR}"
fi
export PHOENIX_LOG_DIR

# GNU sed
if [[ "${PHOENIX_OS}" == 'osx' ]]; then
    readonly PHOENIX_SED_DEFAULT='gsed'
else
    readonly PHOENIX_SED_DEFAULT='sed'
fi
if [[ -z "${PHOENIX_SED+x}" ]]; then
    readonly PHOENIX_SED="${PHOENIX_SED_DEFAULT}"
else
    readonly PHOENIX_SED="${PHOENIX_SED}"
fi
export PHOENIX_SED

# GNU tar
if [[ "${PHOENIX_OS}" == 'osx' ]]; then
    readonly PHOENIX_TAR_DEFAULT='gtar'
else
    readonly PHOENIX_TAR_DEFAULT='tar'
fi
if [[ -z "${PHOENIX_TAR+x}" ]]; then
    readonly PHOENIX_TAR="${PHOENIX_TAR_DEFAULT}"
else
    readonly PHOENIX_TAR="${PHOENIX_TAR}"
fi
export PHOENIX_TAR

# Python
if [[ "${PHOENIX_OS}" == 'osx' ]]; then
    readonly PHOENIX_PYTHON_DEFAULT='/opt/homebrew/bin/python'
else
    readonly PHOENIX_PYTHON_DEFAULT='/usr/bin/python'
fi
if [[ -z "${PHOENIX_PYTHON+x}" ]]; then
    readonly PHOENIX_PYTHON="${PHOENIX_PYTHON_DEFAULT}"
else
    readonly PHOENIX_PYTHON="${PHOENIX_PYTHON}"
fi
export PHOENIX_PYTHON

# Whether we're ONLY building Phoenix for Android
readonly PHOENIX_ANDROID_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_ANDROID_ONLY+x}" ]]; then
    readonly PHOENIX_ANDROID_ONLY="${PHOENIX_ANDROID_ONLY_DEFAULT}"
else
    readonly PHOENIX_ANDROID_ONLY="${PHOENIX_ANDROID_ONLY}"
fi
export PHOENIX_ANDROID_ONLY
if [ "${PHOENIX_ANDROID_ONLY}" == 1 ]; then
    PHOENIX_ANDROID=1
    PHOENIX_LINUX=0
    PHOENIX_LINUX_FLATPAK=0
    PHOENIX_OSX=0
    PHOENIX_OSX_INTEL=0
    PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for Linux
readonly PHOENIX_LINUX_ONLY_DEFAULT=0
if [ "${PHOENIX_NIX}" == 1 ] && [ "${PHOENIX_OS}" != 'osx' ]; then
    # Nix flakes should only build their respective platform
    readonly PHOENIX_LINUX_ONLY=1
elif [[ -z "${PHOENIX_LINUX_ONLY+x}" ]]; then
    readonly PHOENIX_LINUX_ONLY="${PHOENIX_LINUX_ONLY_DEFAULT}"
else
    readonly PHOENIX_LINUX_ONLY="${PHOENIX_LINUX_ONLY}"
fi
export PHOENIX_LINUX_ONLY
if [ "${PHOENIX_LINUX_ONLY}" == 1 ]; then
    PHOENIX_LINUX=1
    PHOENIX_ANDROID=0
    PHOENIX_LINUX_FLATPAK=0
    PHOENIX_OSX=0
    PHOENIX_OSX_INTEL=0
    PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for Linux (Flatpak)
readonly PHOENIX_LINUX_FLATPAK_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_LINUX_FLATPAK_ONLY+x}" ]]; then
    readonly PHOENIX_LINUX_FLATPAK_ONLY="${PHOENIX_LINUX_FLATPAK_ONLY_DEFAULT}"
else
    readonly PHOENIX_LINUX_FLATPAK_ONLY="${PHOENIX_LINUX_FLATPAK_ONLY}"
fi
export PHOENIX_LINUX_FLATPAK_ONLY
if [ "${PHOENIX_LINUX_FLATPAK_ONLY}" == 1 ]; then
    PHOENIX_LINUX_FLATPAK=1
    PHOENIX_ANDROID=0
    PHOENIX_LINUX=0
    PHOENIX_OSX=0
    PHOENIX_OSX_INTEL=0
    PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for OS X
readonly PHOENIX_OSX_ONLY_DEFAULT=0
if [ "${PHOENIX_NIX}" == 1 ] && [ "${PHOENIX_OS}" == 'osx' ]; then
    # Nix flakes should only build their respective platform
    readonly PHOENIX_OSX_ONLY=1
elif [[ -z "${PHOENIX_OSX_ONLY+x}" ]]; then
    readonly PHOENIX_OSX_ONLY="${PHOENIX_OSX_ONLY_DEFAULT}"
else
    readonly PHOENIX_OSX_ONLY="${PHOENIX_OSX_ONLY}"
fi
export PHOENIX_OSX_ONLY
if [ "${PHOENIX_OSX_ONLY}" == 1 ]; then
    PHOENIX_OSX=1
    PHOENIX_ANDROID=0
    PHOENIX_LINUX=0
    PHOENIX_LINUX_FLATPAK=0
    PHOENIX_OSX_INTEL=0
    PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for OS X (Intel)
readonly PHOENIX_OSX_INTEL_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_OSX_INTEL_ONLY+x}" ]]; then
    readonly PHOENIX_OSX_INTEL_ONLY="${PHOENIX_OSX_INTEL_ONLY_DEFAULT}"
else
    readonly PHOENIX_OSX_INTEL_ONLY="${PHOENIX_OSX_INTEL_ONLY}"
fi
