    PHOENIX_OSX_INTEL=1
    PHOENIX_ANDROID=0
    PHOENIX_LINUX=0
    PHOENIX_LINUX_FLATPAK=0
    PHOENIX_OSX=0
    PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for Windows
readonly PHOENIX_WINDOWS_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_WINDOWS_ONLY+x}" ]]; then
    readonly PHOENIX_WINDOWS_ONLY="${PHOENIX_WINDOWS_ONLY_DEFAULT}"
else
    readonly PHOENIX_WINDOWS_ONLY="${PHOENIX_WINDOWS_ONLY}"
fi
export PHOENIX_WINDOWS_ONLY
if [ "${PHOENIX_WINDOWS_ONLY}" == 1 ]; then
    PHOENIX_WINDOWS=1
    PHOENIX_ANDROID=0
    PHOENIX_LINUX=0
    PHOENIX_LINUX_FLATPAK=0
    PHOENIX_OSX=0
    PHOENIX_OSX_INTEL=0
fi

# Whether we're building Phoenix for Android (Default)
readonly PHOENIX_ANDROID_DEFAULT=1
if [ "${PHOENIX_NIX}" == 1 ]; then
    # This makes absolutely no sense for Nix - ensure we never try to build Android there
    readonly PHOENIX_ANDROID=0
elif [[ -z "${PHOENIX_ANDROID+x}" ]]; then
    readonly PHOENIX_ANDROID="${PHOENIX_ANDROID_DEFAULT}"
else
    readonly PHOENIX_ANDROID="${PHOENIX_ANDROID}"
fi
export PHOENIX_ANDROID

# Whether we're building Phoenix for Linux (Default)
readonly PHOENIX_LINUX_DEFAULT=1
if [[ -z "${PHOENIX_LINUX+x}" ]]; then
    readonly PHOENIX_LINUX="${PHOENIX_LINUX_DEFAULT}"
else
    readonly PHOENIX_LINUX="${PHOENIX_LINUX}"
fi
export PHOENIX_LINUX

# Whether we're building Phoenix for Linux (Flatpak) (Default)
readonly PHOENIX_LINUX_FLATPAK_DEFAULT=1
if [[ -z "${PHOENIX_LINUX_FLATPAK+x}" ]]; then
    readonly PHOENIX_LINUX_FLATPAK="${PHOENIX_LINUX_FLATPAK_DEFAULT}"
else
    readonly PHOENIX_LINUX_FLATPAK="${PHOENIX_LINUX_FLATPAK}"
fi
