# Whether we're building Phoenix for OS X (Default)
readonly PHOENIX_OSX_DEFAULT=1
if [[ -z "${PHOENIX_OSX+x}" ]]; then
    readonly PHOENIX_OSX="${PHOENIX_OSX_DEFAULT}"
else
    readonly PHOENIX_OSX="${PHOENIX_OSX}"
fi
export PHOENIX_OSX

# Whether we're building Phoenix for OS X (Intel) (Default)
readonly PHOENIX_OSX_INTEL_DEFAULT=1
if [[ -z "${PHOENIX_OSX_INTEL+x}" ]]; then
    readonly PHOENIX_OSX_INTEL="${PHOENIX_OSX_INTEL_DEFAULT}"
else
    readonly PHOENIX_OSX_INTEL="${PHOENIX_OSX_INTEL}"
fi
export PHOENIX_OSX_INTEL

# Whether we're building Phoenix for Windows (Default)
readonly PHOENIX_WINDOWS_DEFAULT=1
if [ "${PHOENIX_NIX}" == 1 ]; then
    # This makes absolutely no sense for Nix - ensure we never try to build Windows there
    readonly PHOENIX_WINDOWS=0
elif [[ -z "${PHOENIX_WINDOWS+x}" ]]; then
    readonly PHOENIX_WINDOWS="${PHOENIX_WINDOWS_DEFAULT}"
else
    readonly PHOENIX_WINDOWS="${PHOENIX_WINDOWS}"
fi
export PHOENIX_WINDOWS

# Whether we should exclude "NO-MAIL" preferences when building Phoenix
## (ex. for Dove)
readonly PHOENIX_MAIL_DEFAULT=0
if [[ -z "${PHOENIX_MAIL+x}" ]]; then
    readonly PHOENIX_MAIL="${PHOENIX_MAIL_DEFAULT}"
else
    readonly PHOENIX_MAIL="${PHOENIX_MAIL}"
fi
export PHOENIX_MAIL

# Whether we should ONLY build Phoenix standard
readonly PHOENIX_STANDARD_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_STANDARD_ONLY+x}" ]]; then
    readonly PHOENIX_STANDARD_ONLY="${PHOENIX_STANDARD_ONLY_DEFAULT}"
else
    readonly PHOENIX_STANDARD_ONLY="${PHOENIX_STANDARD_ONLY}"
fi
export PHOENIX_STANDARD_ONLY
if [ "${PHOENIX_STANDARD_ONLY}" == 1 ]; then
    PHOENIX_STANDARD=1
    PHOENIX_EXTENDED=0
fi

# Whether we should ONLY build Phoenix extended
readonly PHOENIX_EXTENDED_ONLY_DEFAULT=0
if [ "${PHOENIX_MAIL}" == 1 ]; then
    # Mail only wants/needs extended
    readonly PHOENIX_EXTENDED_ONLY=1
elif [[ -z "${PHOENIX_EXTENDED_ONLY+x}" ]]; then
    readonly PHOENIX_EXTENDED_ONLY="${PHOENIX_EXTENDED_ONLY_DEFAULT}"
else
    readonly PHOENIX_EXTENDED_ONLY="${PHOENIX_EXTENDED_ONLY}"
fi
export PHOENIX_EXTENDED_ONLY
if [ "${PHOENIX_EXTENDED_ONLY}" == 1 ]; then
    PHOENIX_EXTENDED=1
    PHOENIX_STANDARD=0
fi

# Whether we should build Phoenix standard (Default)
readonly PHOENIX_STANDARD_DEFAULT=1
if [[ -z "${PHOENIX_STANDARD+x}" ]]; then
    readonly PHOENIX_STANDARD="${PHOENIX_STANDARD_DEFAULT}"
else
    readonly PHOENIX_STANDARD="${PHOENIX_STANDARD}"
fi
export PHOENIX_STANDARD

# Whether we should build Phoenix extended (Default)
readonly PHOENIX_EXTENDED_DEFAULT=1
if [[ -z "${PHOENIX_EXTENDED+x}" ]]; then
    readonly PHOENIX_EXTENDED="${PHOENIX_EXTENDED_DEFAULT}"
else
    readonly PHOENIX_EXTENDED="${PHOENIX_EXTENDED}"
fi
export PHOENIX_EXTENDED

# Whether we should build Phoenix's specialized configs (Default)
readonly PHOENIX_SPECS_DEFAULT=1
if [ "${PHOENIX_ANDROID_ONLY}" == 1 ] || [ "${PHOENIX_MAIL}" == 1 ]; then
    # Android and Mail never want or need specialized configs
    readonly PHOENIX_SPECS=0
elif [[ -z "${PHOENIX_SPECS+x}" ]]; then
    readonly PHOENIX_SPECS="${PHOENIX_SPECS_DEFAULT}"
else
    readonly PHOENIX_SPECS="${PHOENIX_SPECS}"
fi
export PHOENIX_SPECS

# Whether we should append contents of an additional .cfg file
## Meant for downstream projects (ex. Dove, IronFox, LibreWolf) to simplify the process of overriding/setting additional preferences
readonly PHOENIX_EXTRA_CFG_DEFAULT=0
if [[ -z "${PHOENIX_EXTRA_CFG+x}" ]]; then
    readonly PHOENIX_EXTRA_CFG="${PHOENIX_EXTRA_CFG_DEFAULT}"
else
    readonly PHOENIX_EXTRA_CFG="${PHOENIX_EXTRA_CFG}"
fi
export PHOENIX_EXTRA_CFG

## This points to the location of the .cfg file that we should append the contents of
readonly PHOENIX_EXTRA_CFG_FILE_DEFAULT='undefined'
if [ "${PHOENIX_EXTRA_CFG}" != 1 ] || [ -z "${PHOENIX_EXTRA_CFG_FILE+x}" ]; then
    readonly PHOENIX_EXTRA_CFG_FILE="${PHOENIX_EXTRA_CFG_FILE_DEFAULT}"
elif [[ -f "${PHOENIX_EXTRA_CFG_FILE+x}" ]]; then
    readonly PHOENIX_EXTRA_CFG_FILE="${PHOENIX_EXTRA_CFG_FILE}"
fi
export PHOENIX_EXTRA_CFG_FILE

## This points to the directory where we should put our (final) output files
readonly PHOENIX_EXTRA_CFG_OUTPUT_DIR_DEFAULT='undefined'
if [ "${PHOENIX_EXTRA_CFG}" != 1 ] || [ -z "${PHOENIX_EXTRA_CFG_OUTPUT_DIR+x}" ]; then
    readonly PHOENIX_EXTRA_CFG_OUTPUT_DIR="${PHOENIX_EXTRA_CFG_OUTPUT_DIR_DEFAULT}"
elif [[ -d "${PHOENIX_EXTRA_CFG_OUTPUT_DIR+x}" ]]; then
    readonly PHOENIX_EXTRA_CFG_OUTPUT_DIR="${PHOENIX_EXTRA_CFG_OUTPUT_DIR}"
fi
export PHOENIX_EXTRA_CFG_OUTPUT_DIR

